// Builds CREDITS.md from the data, so the credits can never drift from what the site shows.
const cell = (s) => String(s ?? "").replace(/\|/g, "\\|").replace(/\s+/g, " ").trim();

export function creditsMarkdown(D) {
  const hosted = [], restricted = [];
  D.movements.forEach((m, mi) => m.works.forEach((w, wi) => (w.image ? hosted : restricted).push({ m, mi, w, wi })));
  const out = [
    "# Image credits",
    "",
    "<!-- Generated by `node scripts/fetch-images.mjs` from public/data/movements.js. Do not edit by hand. -->",
    "",
    `${hosted.length} images are hosted with this site, resized from files on Wikimedia Commons. Licences, authors and file pages`,
    "were read from the Commons API. Each file page has the full licence and source details; check it before reusing an image.",
    "",
    "| # | Style | Work | Author | Licence | Source |",
    "| --- | --- | --- | --- | --- | --- |"
  ];
  for (const { m, mi, w, wi } of hosted) {
    const im = w.image;
    const lic = im.licenseUrl ? `[${cell(im.license)}](${im.licenseUrl})` : cell(im.license);
    out.push(`| ${String(mi + 1).padStart(2, "0")}.${wi + 1} | ${cell(m.name.en)} | ${cell(w.t.en)} | ${cell(im.author)} | ${lic} | [Commons](${im.page}) |`);
  }
  out.push("", "## Not reproduced", "",
    `${restricted.length} works are still in copyright. The site shows a placeholder that links to the work instead of an image.`, "");
  for (const { m, w } of restricted) out.push(`- ${cell(w.t.en)}, ${cell(w.a.en)} (${cell(m.name.en)})`);
  return out.join("\n") + "\n";
}
